import React from 'react';

interface SidebarProps {
  currentView: string;
  setCurrentView: (view: string) => void;
  darkMode: boolean;
  setDarkMode: (dark: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setCurrentView, darkMode, setDarkMode }) => {
  const menuItems = [
    { id: 'dashboard', label: "Today's Dashboard", icon: '📊' },
    { id: 'calendar', label: '180-Day Calendar', icon: '📅' },
    { id: 'reports', label: 'Reports & Analytics', icon: '📈' },
    { id: 'rewards', label: 'Rewards & Badges', icon: '🏆' },
    { id: 'settings', label: 'Settings', icon: '⚙️' },
  ];

  return (
    <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} w-64 min-h-screen border-r ${darkMode ? 'border-dark-accent' : 'border-gray-200'}`}>
      <div className="p-6">
        <h2 className="text-xl font-bold text-white mb-8">180-Day Tracker</h2>

        <nav className="space-y-2">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                currentView === item.id
                  ? 'bg-blue-600 text-white'
                  : darkMode 
                    ? 'text-dark-text hover:bg-dark-accent' 
                    : 'text-gray-700 hover:bg-gray-100'
              }`}
            >
              <span className="text-xl">{item.icon}</span>
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="mt-8 pt-8 border-t border-dark-accent">
          <div className="flex items-center justify-between mb-4">
            <span className={`text-sm font-medium ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>
              Dark Mode
            </span>
            <button
              onClick={() => setDarkMode(!darkMode)}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                darkMode ? 'bg-blue-600' : 'bg-gray-300'
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  darkMode ? 'translate-x-6' : 'translate-x-1'
                }`}
              />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
